import {GALLERIES} from './court-geometry.js';
export const SERVE_TYPES={bobble:{name:'Bobble',tip:'A controlled roof-bouncing serve. A useful safe change of pace.',overhead:false},railroad:{name:'Railroad',tip:'Low along the penthouse edge; keeps the receiver tight to the gallery side.',overhead:true},giraffe:{name:'Giraffe',tip:'A high underarm loop off the penthouse; gives time but pushes the receiver deep.',overhead:false},'demi-pique':{name:'Demi-piqué',tip:'From the main-wall side, across to the roof and service wall; awkward descending return.',overhead:true},'side-wall':{name:'Side-wall',tip:'Uses the service wall and penthouse to work the receiver backwards.',overhead:false}};
const deliveries={"bobble":{"short":{"x":-2.6,"y":1.6,"z":9.5,"vx":-5.5,"vy":6,"vz":-9},"long":{"x":-2.6,"y":1.6,"z":9.5,"vx":-3.5,"vy":8,"vz":-10}},"railroad":{"short":{"x":-4.15,"y":2.1,"z":12.1,"vx":-1.5,"vy":4.5,"vz":-18.5},"long":{"x":-4.15,"y":2.1,"z":12.1,"vx":-1.5,"vy":5,"vz":-13.5}},"giraffe":{"short":{"x":-3.9,"y":0.95,"z":10,"vx":-3,"vy":9.5,"vz":-8},"long":{"x":-3.9,"y":0.95,"z":10,"vx":-3,"vy":10,"vz":-9}},"demi-pique":{"short":{"x":3.8,"y":2.1,"z":6.5,"vx":-12,"vy":4,"vz":-14.5},"long":{"x":3.8,"y":2.1,"z":6.5,"vx":-10,"vy":6,"vz":-8}},"side-wall":{"short":{"x":-4.1,"y":1.8,"z":10.7,"vx":-4,"vy":7,"vz":-10.5},"long":{"x":-4.1,"y":1.8,"z":10.7,"vx":-3,"vy":8.5,"vz":-10.5}}};
export const SECOND_GALLERY_LINE=GALLERIES.find(g=>g.z>0&&g.name==='Second gallery').z;
export function serviceBall(length='long',style='bobble'){return {...deliveries[style in deliveries?style:'bobble'][length==='short'?'short':'long']};}
export function servicePosition(style='bobble',scale={x:1,y:1,z:1}){const b=serviceBall('long',style);return {x:b.x-.2*scale.x,z:b.z+.3*scale.z};}
export function chooseComputerServe(character,faults=0,random=Math.random){if(faults||character.ratings.intelligence<35)return 'bobble';const types=Object.keys(SERVE_TYPES);return types[Math.min(types.length-1,Math.floor(random()*types.length))];}

export const canReturnService=b=>!b.serve||!!(b.roof&&b.crossed);
